160:     public static class Session {
161:         private final int mAppId;
162:         private final DexMetadataHelper.DexMetadataInfo mDmInfo;
163:         private final DetailedDexInfo mDexInfo;
164:         private String mCompilerFilter;
165:         private final String mCompilationReason;
166:         private final List<Abi> mAbis;
167: 
168:         private boolean mIsEnabled = true;
169:         private final Map<Abi, Result> mResultsToRecord = new HashMap<>();
170: 
171:         public Session(int appId, @NonNull DexMetadataHelper.DexMetadataInfo dmInfo,
172:                 @NonNull DetailedDexInfo dexInfo, @NonNull String compilerFilter,
173:                 @NonNull String compilationReason, @NonNull List<Abi> abis) {
174:             mAppId = appId;
175:             mDmInfo = dmInfo;
176:             mDexInfo = dexInfo;
177:             mCompilerFilter = compilerFilter;
178:             mCompilationReason = compilationReason;
179:             mAbis = new ArrayList<>(abis);
180: 
181:             // By default, set the results for all ABIs to "Not Run"
182:             for (Abi abi : abis) {
183:                 mResultsToRecord.put(abi,
184:                         new Result(
185:                                 Dex2OatResult.notRun(), 0L /* sizeBytes */, 0L /* wallTimeMs */));
186:             }
187:         }
188: 
189:         public void disable() {
190:             mIsEnabled = false;
191:         }
192: 
193:         public void setCompilerFilter(@NonNull String compilerFilter) {
194:             mCompilerFilter = compilerFilter;
195:         }
196: 
197:         public void recordResultForAbi(
198:                 @NonNull Abi abi, @NonNull Dex2OatResult result, long sizeBytes, long wallTimeMs) {
199:             mResultsToRecord.replace(abi, new Result(result, sizeBytes, wallTimeMs));
200:             mAbis.remove(abi);
201:         }
202: 
203:         public void recordResultForRemainingAbis(@NonNull Dex2OatResult result) {
204:             for (Abi abi : mAbis) {
205:                 mResultsToRecord.replace(
206:                         abi, new Result(result, 0L /* sizeBytes */, 0L /* wallTimeMs */));
207:             }
208:             mAbis.clear();
209:         }
210: 
211:         public void report() {
212:             if (!mIsEnabled) {
213:                 return;
214:             }
215: 
216:             for (Map.Entry<Abi, Result> entry : mResultsToRecord.entrySet()) {
217:                 Abi abi = entry.getKey();
218:                 Result result = entry.getValue();
219:                 ArtStatsLog.write(ArtStatsLog.ART_DEX2OAT_REPORTED, mAppId,
220:                         translateCompilerFilter(mCompilerFilter),
221:                         translateCompilationReason(mCompilationReason),
222:                         translateDexMetadataType(mDmInfo.type()), getApkType(mDexInfo),
223:                         translateIsa(abi.isa()), result.dex2OatResult.status,
224:                         result.dex2OatResult.exitCode, result.dex2OatResult.signal,
225:                         (int) (result.sizeBytes / 1024), (int) result.wallTimeMs);
226:             }
227:         }
228: 
229:         public record Result(Dex2OatResult dex2OatResult, long sizeBytes, long wallTimeMs) {}
230:     }
