433: static int VMRuntime_getSystemDaemonNiceness() {
434:   // We use a priority lower than the default for the system daemon threads (eg HeapTaskDaemon) to
435:   // avoid jank due to CPU contention between GC and other UI-related threads. b/36631902.
436:   // We may use a native priority that doesn't have a corresponding java.lang.Thread-level priority.
437:   // Currently we use a niceness value between those corresponding to priority 4 and 5, which
438:   // matches the traditional niceness 4 value with the traditional mapping.
439:   static int systemDaemonNiceValue =
440:       (6 * Thread::PriorityToNiceness(5) + 4 * Thread::PriorityToNiceness(4) + 5) / 10;
441:   return systemDaemonNiceValue;
442: }
