82:     public void dumpPackage(@NonNull PrintWriter pw,
83:             @NonNull PackageManagerLocal.FilteredSnapshot snapshot,
84:             @NonNull PackageState pkgState) {
85:         if (pkgState.isApex() || pkgState.getAndroidPackage() == null) {
86:             return;
87:         }
88: 
89:         var ipw = new IndentingPrintWriter(pw);
90: 
91:         String packageName = pkgState.getPackageName();
92:         ipw.printf("[%s]\n", packageName);
93: 
94:         List<DexContainerFileDexoptStatus> statuses =
95:                 mInjector.getArtManagerLocal()
96:                         .getDexoptStatus(snapshot, packageName)
97:                         .getDexContainerFileDexoptStatuses();
98:         Map<String, CheckedSecondaryDexInfo> secondaryDexInfoByDexPath =
99:                 mInjector.getDexUseManager()
100:                         .getCheckedSecondaryDexInfo(
101:                                 packageName, false /* excludeObsoleteDexesAndLoaders */)
102:                         .stream()
103:                         .collect(Collectors.toMap(
104:                                 CheckedSecondaryDexInfo::dexPath, Function.identity()));
105: 
106:         // Use LinkedHashMap to keep the order. They are ordered by their split indexes.
107:         var primaryStatusesByDexPath =
108:                 new LinkedHashMap<String, List<DexContainerFileDexoptStatus>>();
109:         // Use TreeMap to force lexicographical order.
110:         var secondaryStatusesByDexPath = new TreeMap<String, List<DexContainerFileDexoptStatus>>();
111:         for (DexContainerFileDexoptStatus fileStatus : statuses) {
112:             if (fileStatus.isPrimaryDex()) {
113:                 primaryStatusesByDexPath
114:                         .computeIfAbsent(fileStatus.getDexContainerFile(), k -> new ArrayList<>())
115:                         .add(fileStatus);
116:             } else if (secondaryDexInfoByDexPath.containsKey(fileStatus.getDexContainerFile())) {
117:                 // The condition above is false only if a change occurs between
118:                 // `getDexoptStatus` and `getSecondaryDexInfo`, which is an edge case.
119:                 secondaryStatusesByDexPath
120:                         .computeIfAbsent(fileStatus.getDexContainerFile(), k -> new ArrayList<>())
121:                         .add(fileStatus);
122:             }
123:         }
124: 
125:         ipw.increaseIndent();
126:         for (List<DexContainerFileDexoptStatus> fileStatuses : primaryStatusesByDexPath.values()) {
127:             dumpPrimaryDex(ipw, snapshot, fileStatuses, packageName);
128:         }
129:         if (!secondaryStatusesByDexPath.isEmpty()) {
130:             ipw.println("known secondary dex files:");
131:             ipw.increaseIndent();
132:             for (Map.Entry<String, List<DexContainerFileDexoptStatus>> entry :
133:                     secondaryStatusesByDexPath.entrySet()) {
134:                 dumpSecondaryDex(ipw, snapshot, entry.getValue(), packageName,
135:                         secondaryDexInfoByDexPath.get(entry.getKey()));
136:             }
137:             ipw.decreaseIndent();
138:         }
139:         ipw.decreaseIndent();
