98: bool OdrCompilationLog::Read() {
99:   std::ifstream ifs(log_path_);
100:   if (!ifs.good()) {
101:     return false;
102:   }
103: 
104:   std::string log_version;
105:   ifs >> log_version >> std::ws;
106:   if (log_version != kLogVersion) {
107:     return false;
108:   }
109: 
110:   while (!ifs.eof()) {
111:     OdrCompilationLogEntry entry;
112:     ifs >> entry;
113:     if (ifs.fail()) {
114:       entries_.clear();
115:       return false;
116:     }
117:     entries_.push_back(entry);
118:   }
119: 
120:   return true;
121: }
