92: void TraceData::AppendToLongRunningMethods(const uint8_t* buffer, size_t size) {
93:   MutexLock mu(Thread::Current(), trace_data_lock_);
94:   if (curr_buffer_ == nullptr) {
95:     curr_buffer_.reset(new uint8_t[kBufSizeForEncodedData]);
96:     curr_index_ = 0;
97:   }
98:   if (curr_index_ + size <= kBufSizeForEncodedData) {
99:     memcpy(curr_buffer_.get() + curr_index_, buffer, size);
100:     curr_index_ += size;
101:   } else {
102:     size_t remaining_bytes = kBufSizeForEncodedData - curr_index_;
103:     if (remaining_bytes != 0) {
104:       memcpy(curr_buffer_.get() + curr_index_, buffer, remaining_bytes);
105:     }
106:     overflow_buffers_.push_back(std::move(curr_buffer_));
107:     curr_buffer_.reset(new uint8_t[kBufSizeForEncodedData]);
108:     memcpy(curr_buffer_.get(), buffer + remaining_bytes, size - remaining_bytes);
109:   }
110: }
