112: void TraceProfiler::AllocateBuffer(Thread* thread) {
113:   if (!ShouldEnableProfileCode()) {
114:     return;
115:   }
116: 
117:   Thread* self = Thread::Current();
118:   MutexLock mu(self, *Locks::trace_lock_);
119:   if (!profile_in_progress_) {
120:     return;
121:   }
122: 
123:   auto buffer = new uintptr_t[kAlwaysOnTraceBufSize];
124:   size_t index = kAlwaysOnTraceBufSize;
125:   if (trace_data_->GetTraceType() == LowOverheadTraceType::kAllMethods) {
126:     memset(buffer, 0, kAlwaysOnTraceBufSize * sizeof(uintptr_t));
127:   } else {
128:     DCHECK(trace_data_->GetTraceType() == LowOverheadTraceType::kLongRunningMethods);
129:     // For long running methods add a placeholder method exit entry. This avoids
130:     // additional checks on method exits to see if the previous entry is valid.
131:     index--;
132:     buffer[index] = 0x1;
133:   }
134:   thread->SetMethodTraceBuffer(buffer, index);
