153:         : StackVisitor(thread_in, context, StackVisitor::StackWalkKind::kSkipInlinedFrames) {}
154: 
155:     bool VisitFrame() override REQUIRES_SHARED(Locks::mutator_lock_) {
156:       ArtMethod* m = GetMethod();
157:       if (m != nullptr && !m->IsRuntimeMethod()) {
158:         if (GetCurrentShadowFrame() != nullptr) {
159:           // TODO(mythria): Support low-overhead tracing for the switch interpreter.
160:         } else {
161:           const OatQuickMethodHeader* method_header = GetCurrentOatQuickMethodHeader();
162:           if (method_header == nullptr) {
163:             // TODO(mythria): Consider low-overhead tracing support for the GenericJni stubs.
164:           } else {
165:             // Ignore nterp methods. We don't support recording trace events in nterp.
166:             if (!method_header->IsNterpMethodHeader()) {
167:               stack_methods_.push_back(m);
168:             }
169:           }
170:         }
171:       }
172:       return true;
173:     }
174: 
175:     std::vector<ArtMethod*> stack_methods_;
