183:   uint64_t init_ts = TimestampCounter::GetTimestamp();
184:   // Set the lsb to 0 to indicate method entry.
185:   init_ts = init_ts & ~1;
186:   size_t index = kAlwaysOnTraceBufSize - 1;
187:   for (auto smi = visitor.stack_methods_.rbegin(); smi != visitor.stack_methods_.rend(); smi++) {
188:     method_trace_buffer[index--] = reinterpret_cast<uintptr_t>(*smi);
189:     method_trace_buffer[index--] = init_ts;
190: 
191:     if (index < kMaxEntriesAfterFlush) {
192:       // To keep the implementation simple, ignore methods deep down the stack. If the call stack
193:       // unwinds beyond this point then we will see method exits without corresponding method
194:       // entries.
195:       break;
