189: // A closure used by Thread::Dump.
190: class DumpCheckpoint final : public Closure {
191:  public:
192:   DumpCheckpoint(bool dump_native_stack)
193:       : lock_("Dump checkpoint lock", kGenericBottomLock),
194:         os_(),
195:         // Avoid verifying count in case a thread doesn't end up passing through the barrier.
196:         // This avoids a SIGABRT that would otherwise happen in the destructor.
197:         barrier_(0, /*verify_count_on_shutdown=*/false),
198:         unwinder_(std::vector<std::string>{}, std::vector<std::string> {"oat", "odex"}),
