200:     unwinder_.set_check_global_elf_cache(true);
201:   }
202: 
203:   void Run(Thread* thread) override {
204:     // Note thread and self may not be equal if thread was already suspended at the point of the
205:     // request.
206:     Thread* self = Thread::Current();
207:     CHECK(self != nullptr);
208:     std::ostringstream local_os;
209:     Locks::mutator_lock_->AssertSharedHeld(self);
210:     Thread::DumpOrder dump_order = thread->Dump(local_os, unwinder_, dump_native_stack_);
211:     {
212:       MutexLock mu(self, lock_);
213:       // Sort, so that the most interesting threads for ANR are printed first (ANRs can be trimmed).
214:       std::pair<Thread::DumpOrder, uint32_t> sort_key(dump_order, thread->GetThreadId());
215:       os_.emplace(sort_key, std::move(local_os));
216:     }
217:     barrier_.Pass(self);
218:   }
219: 
220:   // Called at the end to print all the dumps in sequential prioritized order.
221:   void Dump(Thread* self, std::ostream& os) {
222:     MutexLock mu(self, lock_);
223:     for (const auto& it : os_) {
224:       os << it.second.str() << std::endl;
225:     }
226:   }
