597: bool MemberSignature::DoesPrefixMatch(const std::string& prefix) const {
598:   size_t pos = 0;
599:   for (const char* part : GetSignatureParts()) {
600:     size_t count = std::min(prefix.length() - pos, strlen(part));
601:     if (prefix.compare(pos, count, part, 0, count) == 0) {
602:       pos += count;
603:     } else {
604:       return false;
605:     }
606:   }
607:   // We have a complete match if all parts match (we exit the loop without
608:   // returning) AND we've matched the whole prefix.
609:   return pos == prefix.length();
610: }
