570: jint JavaVMExt::HandleGetEnv(/*out*/void** env, jint version) {
571:   static constexpr size_t kMaxStackEntries = 4u;
572:   InlinedVector<GetEnvHook, kMaxStackEntries> env_hooks;
573:   {
574:     ReaderMutexLock rmu(Thread::Current(), env_hooks_lock_);
575:     for (GetEnvHook hook : env_hooks_) {
576:       env_hooks.push_back(hook);
577:     }
578:   }
579:   for (GetEnvHook hook : env_hooks.GetArray()) {
580:     jint res = hook(this, env, version);
581:     if (res == JNI_OK) {
582:       return JNI_OK;
583:     } else if (res != JNI_EVERSION) {
584:       LOG(ERROR) << "Error returned from a plugin GetEnv handler! " << res;
585:       return res;
586:     }
587:   }
588:   LOG(ERROR) << "Bad JNI version passed to GetEnv: " << version;
589:   return JNI_EVERSION;
